import React, { useContext } from 'react';

import { Link } from 'react-router-dom';

import { getHikingJointlyEquipments } from '@apps/Hiking/@services/hikingJointlyEquipment.service';
import { getHikingTransfers } from '@apps/Hiking/@services/hikingTransfers.service';
import { IHikingJointlyEquipment } from '@apps/Hiking/@types/hikingJointlyEquipment.types';
import { IHikingTransfer } from '@apps/Hiking/@types/hikingTransfers.types';
import { IProductForPrint } from '@apps/Hiking/menu/components/HikingMenuPrintStickers/mapper';
import PageLoader from '@components/PageLoader';
import { dateRangeToLocaleString } from '@helpers/dateHelper';
import { declOfNum } from '@helpers/formatHelper';
import { round } from '@helpers/mathHelper';
import { getShortName } from '@helpers/name.helper';
import { err } from '@helpers/notificationHelper';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import { AuthContext } from '../../../../contexts/AuthContext';
import { weekDays, weekDaysR } from '../../../../resources/dates';
import { IFirstAidKitSMedicament } from '../../../Medicaments/@types/firstAidKit.types';
import { getFirstAidKidForHikingAsync } from '../../../Medicaments/services/firstAidKit.services';
import { getHikingEquip } from '../../@services/equip.service';
import { getHikingDataAsync } from '../../@services/hiking.service';
import { getHikingDuty } from '../../@services/hikingDuty.service';
import { getHikingProductsForPrint } from '../../@services/hikingMenu.service';
import { getHikingSchedule } from '../../@services/hikingSchedule.service';
import { IHikingEquip } from '../../@types/equip.types';
import { IHikingDuty, IHikingScheduleItem } from '../../@types/hiking.baseTypes';
import { IHikingData } from '../../@types/hiking.types';
import { previewEquipModal } from '../HikingEquip/previewEquip/previewEduipModal';

interface IHikingMyProps {
  id_hiking: number;
}

const HikingMy: React.FC<IHikingMyProps> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [hikingSchedule, setHikingSchedule] = React.useState<IHikingScheduleItem[]>([]);
  const [hikingDuty, setHikingDuty] = React.useState<IHikingDuty[]>([]);
  const [hikingEquip, setHikingEquip] = React.useState<IHikingEquip[]>([]);
  const [hikingEquipNotConfirmed, setHikingEquipNotConfirmed] = React.useState<IHikingEquip[]>([]);
  const [fakItems, setFakItems] = React.useState<IFirstAidKitSMedicament[]>([]);
  const [product, setProducts] = React.useState<IProductForPrint[]>([]);
  const [watercraft, setWatercraft] = React.useState<IHikingJointlyEquipment[]>([]);
  const [tents, setTents] = React.useState<IHikingJointlyEquipment[]>([]);
  const [transfers, setTransfers] = React.useState<IHikingTransfer[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);

  const authContext = useContext(AuthContext);

  React.useEffect(() => {
    const start = async () => {
      await getHikingDataAsync(id_hiking).then(setHikingData);
      await getHikingSchedule(id_hiking).then(setHikingSchedule);
      await getHikingDuty(id_hiking).then(setHikingDuty);
      await getHikingEquip(id_hiking, true).then(setHikingEquip);
      await getHikingEquip(id_hiking, false).then(setHikingEquipNotConfirmed);
      await getFirstAidKidForHikingAsync(id_hiking).then(setFakItems);
      await getHikingProductsForPrint(id_hiking).then(setProducts);
      await getHikingJointlyEquipments(id_hiking, 'tent').then(setTents);
      await getHikingJointlyEquipments(id_hiking, 'watercraft').then(setWatercraft);
      await getHikingTransfers(id_hiking).then(setTransfers);
    };

    start()
      .catch(err)
      .finally(() => setIsLoading(false));
  }, [id_hiking]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (!hikingData) {
    return null;
  }

  if (!authContext.user) {
    return <p>Ты кто?</p>;
  }

  const iHiker = hikingData.hikers.find((h) => h.idUser === authContext.user!.id);

  if (!iHiker) {
    return <p>Герман, это не ваша кровать</p>;
  }

  const myFakItems = fakItems.filter((x) => x.assignee?.id === iHiker.idUser);
  const commonFakItems = fakItems.filter((x) => x.count_for_each > 0);
  const myProducts = product.filter((x) => x.user?.id === iHiker.idUser && x.isForced);
  const myTents = tents.filter((t) => t.members.some((u) => u.user.id === authContext.user!.id));
  const myWatercraft = watercraft.filter((t) =>
    t.members.some((u) => u.user.id === authContext.user!.id),
  );
  const myTransfers = transfers.filter((t) =>
    t.members.some((u) => u.user.id === authContext.user!.id),
  );

  const hikingEquipForOthers = hikingEquipNotConfirmed.filter(
    (h) => h.fromUser?.id === iHiker.idUser,
  );

  const myProductsMap = myProducts.reduce<
    Record<number, { amount: number; items: IProductForPrint[]; name: string }>
  >((acc, val) => {
    if (!acc[val.idProduct])
      acc[val.idProduct] = {
        amount: 0,
        name: val.name + (val.ex ? `(ex. ${val.ex.name})` : ``),
        items: [],
      };

    acc[val.idProduct].amount += val.amount;
    acc[val.idProduct].items.push(val);

    return acc;
  }, {});

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name ?? '' },
          { href: `/hiking/${id_hiking}/my`, text: 'Личная страничка', active: true },
        ]}
      />
      <h3 className="mb-3">Мой поход «{hikingData.name}»</h3>
      <PohRow>
        <PohCol sm={12} className="border-end">
          <h5>Введение</h5>
          <p>
            Привет, {iHiker.name}. На этой странице я расскажу тебе о походе «{hikingData.name}» и о
            твоей роли в нём.
            <br />
            Здесь будет много полезной информации, внимательно с ней ознакомься.
          </p>

          <h5>Продолжительность</h5>
          <p>
            {iHiker.dateFrom
              ? `Ты решил${iHiker.isGirl ? 'а' : ''} присоединиться к походу позже основной группы. Ждем тебя ${iHiker.dateFrom.toLocaleString(
                  undefined,
                  {
                    dateStyle: 'short',
                    timeStyle: 'short',
                  },
                )}. Для основной группы `
              : `Наши `}
            приключения начнутся {weekDaysR[hikingSchedule[0].start.getDay()]}{' '}
            {hikingSchedule[0].start.toLocaleDateString()}. В{' '}
            {hikingSchedule[0].start.toLocaleTimeString()} по плану{' '}
            <em>{hikingSchedule[0].name}</em>. <br /> Основная (ходовая) часть похода займет{' '}
            {round(hikingData.duration, 1)}{' '}
            {declOfNum(Math.ceil(hikingData.duration), ['день', 'дня', 'дней'])}, начало
            запланировано на {hikingData.start.toLocaleString()} (
            {weekDays[hikingData.start.getDay()]}), а завершение на{' '}
            {hikingData.finish.toLocaleString()} ({weekDays[hikingData.finish.getDay()]}) <br />
            Заключительной частью похода будет{' '}
            <em>{hikingSchedule[hikingSchedule.length - 1].name}</em>
            {` `}
            {weekDaysR[hikingSchedule[hikingSchedule.length - 1].start.getDay()]}
            {` `}
            {hikingSchedule[hikingSchedule.length - 1].finish.toLocaleString(undefined, {
              dateStyle: 'short',
              timeStyle: 'short',
            })}
            .{' '}
            {iHiker.dateTo
              ? `Но ты решил${iHiker.isGirl ? 'а' : ''} завершить поход пораньше, надеемся дела того стоят. Ты будешь с нами до ${iHiker.dateTo.toLocaleString(
                  undefined,
                  {
                    dateStyle: 'short',
                    timeStyle: 'short',
                  },
                )}, спасибо и на этом) `
              : ``}
            <br />
            Подробнее с планом можно ознакомиться на{' '}
            <Link to={`/hiking/${id_hiking}`}>странице похода</Link> или отдельной странице с{' '}
            <Link to={`/hiking/${id_hiking}/schedule`}>планом</Link>
          </p>

          {hikingSchedule.filter((d) => d.is_self_sufficiency).length > 0 && (
            <>
              <h5>Самообеспечение</h5>
              <p>
                Обрати пожалуйста внимание, что часть пунктов нашего плана подразумевает
                самостоятельную подготовку.
              </p>
              <table className="table table-sm table-bordered">
                <thead>
                  <tr>
                    <th>Пункт плана</th>
                    <th>Дата</th>
                    <th>Примечания</th>
                  </tr>
                </thead>
                <tbody>
                  {hikingSchedule
                    .filter((d) => d.is_self_sufficiency)
                    .map((x) => {
                      return (
                        <tr key={x.id}>
                          <td>
                            <small>{x.name}</small>
                          </td>
                          <td>{dateRangeToLocaleString(x.start, x.finish)}</td>
                          <td>{x.description || '-'}</td>
                        </tr>
                      );
                    })}
                </tbody>
              </table>
            </>
          )}

          <h5>Участники</h5>
          <p>
            Вся наша дружная команда - это {hikingData.hikers.length}{' '}
            {declOfNum(hikingData.hikers.length, ['человек', 'человека', 'человек'])}
            {` (`}
            {hikingData.hikers.filter((x) => x.isGirl).length}{' '}
            {declOfNum(hikingData.hikers.filter((x) => x.isGirl).length, [
              'девушка',
              'девушки',
              'девушек',
            ])}
            {` `}и {hikingData.hikers.filter((x) => !x.isGirl).length}{' '}
            {declOfNum(hikingData.hikers.filter((x) => !x.isGirl).length, [
              'парень',
              'парня',
              'парней',
            ])}
            )
          </p>
          <p>
            <ul>
              {hikingData.hikers.map((h) => {
                return (
                  <li key={h.idUser}>
                    <Link to={`/user/${h.idUser}`}>{[h.name, h.surname].join('\u00a0')}</Link>{' '}
                    {h.positions.length > 0 && (
                      <em>({h.positions.map((x) => x.name).join(', ')})</em>
                    )}
                    {(h.dateFrom || h.dateTo) && (
                      <small className="text-muted">
                        &nbsp; (c нами с {h.dateFrom ? h.dateFrom.toLocaleString() : 'начала'}
                        &nbsp;до {h.dateTo ? h.dateTo.toLocaleString() : 'конца'})
                      </small>
                    )}
                  </li>
                );
              })}
            </ul>
          </p>
          {iHiker.positions.length > 0 && (
            <section className="mb-3">
              <h5>Должность</h5>
              <p>
                Как ты уже наверно заметил{iHiker.isGirl ? 'а' : ''},{' '}
                {iHiker.positions.length > 1 ? 'твои должности' : 'твоя должность'} в походе это{' '}
                {iHiker.positions.map((x) => x.name).join(', ')}. Внимательно прочитай и как следует
                подготовься к походу.
              </p>

              {iHiker.positions.map((x) => (
                <div key={x.id}>
                  <em>{x.name}</em>
                  <br />
                  <small dangerouslySetInnerHTML={{ __html: x.description }} />
                </div>
              ))}
            </section>
          )}

          {(hikingEquip.filter((d) => d.user?.id === iHiker.idUser).length > 0 ||
            hikingEquipNotConfirmed.filter((d) => d.user?.id === iHiker.idUser).length > 0) && (
            <>
              <h5>Общее снаряжение</h5>
              <p>
                Тебе поручена очень важная часть общественного снаряжения, не забудь взять все это в
                поход. Т.к. снаряжение общественное, оно точно пригодится точно не только тебе, а
                возможно вообще всем.
                <ul>
                  {hikingEquip
                    .filter((d) => d.user?.id === iHiker.idUser)
                    .map((x) => {
                      return (
                        <li key={x.id}>
                          {x.name} весом {x.weight}г.{' '}
                          {x.fromUser ? (
                            <span className="text-info">(надо взять у {x.fromUser.name})</span>
                          ) : (
                            ''
                          )}
                        </li>
                      );
                    })}
                </ul>
                {hikingEquipNotConfirmed.filter((d) => d.user?.id === iHiker.idUser && !d.isConfirm)
                  .length > 0 && (
                  <>
                    На свое усмотрение можешь брать или не брать
                    <ul>
                      {hikingEquipNotConfirmed
                        .filter((d) => d.user?.id === iHiker.idUser && !d.isConfirm)
                        .map((x) => {
                          return (
                            <li key={x.id}>
                              {x.name} весом {x.weight}г.{' '}
                              {x.fromUser ? (
                                <span className="text-info">(надо взять у {x.fromUser.name})</span>
                              ) : (
                                ''
                              )}
                            </li>
                          );
                        })}
                    </ul>
                  </>
                )}
              </p>
            </>
          )}

          {hikingEquipForOthers.length > 0 && (
            <p>
              Нужно передать другим участникам следующее снаряжение:
              <ul>
                {hikingEquipForOthers.map((x) => {
                  return (
                    <li key={x.id}>
                      {x.name} весом {x.weight}г. для{' '}
                      {x.user ? <span className="text-info"> {x.user.name}</span> : ''}
                    </li>
                  );
                })}
              </ul>
            </p>
          )}

          {Object.values(myProductsMap).length > 0 && (
            <>
              <h5>Твои продукты</h5>
              <p>
                Помимо всего{' '}
                <Link to={`/hiking/${id_hiking}/menu/matrix`}>разнообразия продуктов</Link> из
                которых мы будем готовить еду в походе, есть {Object.values(myProductsMap).length} -
                за которые отвечаешь именно ты. Ты будешь их носить весь поход и выдавать по мере
                надобности.
                <ul>
                  {Object.entries(myProductsMap).map(([key, x]) => {
                    return (
                      <li key={key}>
                        {x.name}, всего {round(x.amount * hikingData.hikers.length)} г. на{' '}
                        {x.items.length} {declOfNum(x.items.length, ['раз', 'раза', 'раз'])}.
                      </li>
                    );
                  })}
                </ul>
                <br />
                На странице <Link to={`/hiking/${id_hiking}/menu`}>меню</Link> можно увидеть по
                приемам пищи чего и сколько предстоит съесть
              </p>
            </>
          )}

          {(myFakItems.length > 0 || commonFakItems.length > 0) && (
            <>
              <h5>Аптечка</h5>
              {myFakItems.length > 0 && (
                <p>
                  Медицинская <Link to={`/hiking/${id_hiking}/fak`}>аптечка</Link> для этого похода
                  спланирована так, что за {myFakItems.length}{' '}
                  {declOfNum(myFakItems.length, ['элемент', 'элемента', 'элементов'])} аптечки
                  отвечаешь именно ты, {iHiker.name}. Проследи чтобы все это было у тебя в наличии.
                  Это может понадобиться в любой момент любому участнику похода.
                  <ul>
                    {myFakItems.map((x) => {
                      return (
                        <li key={x.id}>
                          {x.medicament.name} {x.amount}{' '}
                          {x.medicament.form
                            ? getShortName(x.medicament.form.name.toLowerCase())
                            : ''}{' '}
                          <em>{x.comment ?? ''}</em>
                        </li>
                      );
                    })}
                  </ul>
                </p>
              )}

              {commonFakItems.length > 0 && (
                <p>
                  Каждому участнику похода необходимо при себе иметь:
                  <ul>
                    {commonFakItems.map((x) => {
                      return (
                        <li key={x.id}>
                          {x.medicament.name} {x.count_for_each}{' '}
                          {x.medicament.form
                            ? getShortName(x.medicament.form.name.toLowerCase())
                            : ''}{' '}
                          <em>{x.comment ?? ''}</em>
                        </li>
                      );
                    })}
                  </ul>
                </p>
              )}
            </>
          )}

          {hikingDuty.length > 0 && (
            <>
              <h5>Дежурства</h5>
              <p>
                По <Link to={`/hiking/${id_hiking}/duty`}>графику дежурств</Link> тебе предстоит
                дежурить {hikingDuty.filter((d) => d.id_user === iHiker.idUser).length}{' '}
                {declOfNum(hikingDuty.filter((d) => d.id_user === iHiker.idUser).length, [
                  'раз',
                  'раза',
                  'раз',
                ])}
                <ul>
                  {hikingDuty
                    .filter((d) => d.id_user === iHiker.idUser)
                    .map((x) => {
                      return (
                        <li key={x.id}>
                          {x.date.toLocaleDateString()} {weekDays[x.date.getDay()]}
                        </li>
                      );
                    })}
                </ul>
              </p>
            </>
          )}

          {myTents.length > 0 && (
            <section>
              <h5>{myTents.length > 1 ? 'Палатки' : 'Палатка'}</h5>
              {myTents.map((t) => {
                return (
                  <div key={t.id}>
                    <p>
                      Тебе будешь сладко спать в палатке{' '}
                      <strong>
                        {t.equip ? (
                          <a
                            onClick={(e) => {
                              e.preventDefault();
                              previewEquipModal(t.equip!);
                            }}
                            href="#"
                          >
                            {t.name}
                          </a>
                        ) : (
                          t.name
                        )}
                      </strong>{' '}
                      {t.comment ? ` (${t.comment})` : ''}
                      {t.members.length === 1
                        ? ' в гордом одиночестве.'
                        : `. Вместе с тобой в палатке ${t.members.length == 2 ? 'будет' : 'будут'} ${(() => {
                            const formatter = new Intl.ListFormat('default', {
                              style: 'long',
                              type: 'conjunction',
                            });
                            return formatter.format(
                              t.members
                                .filter((x) => x.user.id !== authContext.user?.id)
                                .map(
                                  (m) =>
                                    `${m.user.name} ${m.user.surname}${m.comment.length > 0 ? ` (${m.comment})` : ''}`,
                                ),
                            );
                          })()}.`}
                    </p>
                    {t.equip && hikingEquip.some((q) => q.id_parent === t.equip?.id) && (
                      <p>
                        У кого части палатки:
                        <ul>
                          {hikingEquip
                            .filter((q) => q.id_parent === t.equip?.id)
                            .map((x) => {
                              return (
                                <li key={x.id}>
                                  <strong>{x.name}</strong> -{' '}
                                  <span className="text-info">{x.user?.name}</span>{' '}
                                </li>
                              );
                            })}
                        </ul>
                      </p>
                    )}
                  </div>
                );
              })}
            </section>
          )}
          {myWatercraft.length > 0 && (
            <section>
              <h5>{myWatercraft.length > 1 ? 'Плавсредство' : 'Плавсредства'}</h5>
              {myWatercraft.map((t) => {
                return (
                  <div key={t.id}>
                    <p>
                      В качестве плавсредства у тебя будет{' '}
                      <strong>
                        {t.equip ? (
                          <a
                            onClick={(e) => {
                              e.preventDefault();
                              previewEquipModal(t.equip!);
                            }}
                            href="#"
                          >
                            {t.name}
                          </a>
                        ) : (
                          t.name
                        )}
                      </strong>{' '}
                      {t.comment ? ` (${t.comment})` : ''}
                      {t.members.length === 1
                        ? `. Ты ${iHiker.isGirl ? 'единственная командирша' : 'единственный командир'} своего судна. Всё в твоих руках.`
                        : `. Вместе с тобой вести судно ${t.members.length == 2 ? 'будет' : 'будут'} ${(() => {
                            const formatter = new Intl.ListFormat('default', {
                              style: 'long',
                              type: 'conjunction',
                            });
                            return formatter.format(
                              t.members
                                .filter((x) => x.user.id !== authContext.user?.id)
                                .map(
                                  (m) =>
                                    `${m.user.name} ${m.user.surname}${m.comment.length > 0 ? ` (${m.comment})` : ''}`,
                                ),
                            );
                          })()}.`}
                    </p>
                    {t.equip && hikingEquip.some((q) => q.id_parent === t.equip?.id) && (
                      <p>
                        У кого части плавсредства:
                        <ul>
                          {hikingEquip
                            .filter((q) => q.id_parent === t.equip?.id)
                            .map((x) => {
                              return (
                                <li key={x.id}>
                                  <strong>{x.name}</strong> -{' '}
                                  <span className="text-info">{x.user?.name}</span>{' '}
                                </li>
                              );
                            })}
                        </ul>
                      </p>
                    )}
                  </div>
                );
              })}
            </section>
          )}
          {myTransfers.length > 0 && (
            <section>
              <h5>{myTransfers.length > 1 ? 'Трансферы' : 'Трансфер'}</h5>
              <p>
                Чтобы добраться к месту старта похода и выбраться обратно тебе предстоит{' '}
                {myTransfers.length}{' '}
                {declOfNum(myTransfers.length, ['трансфер', 'трансфера', 'трансферов'])}.
              </p>
              <ol>
                {myTransfers.map((t) => {
                  return (
                    <li key={t.id}>
                      На {t.car.name} ({t.car.number}, {t.car.color}) вы стартуете{' '}
                      {t.start.date.toLocaleString()} ({t.start.description}), а финишируете{' '}
                      {t.finish.date.toLocaleString()} ({t.finish.description}). <br />
                      {t.comment.length > 0 ? (
                        <>
                          {t.comment}.<br />
                        </>
                      ) : (
                        ''
                      )}
                      За рулём будет <strong className="text-success">{t.driver.name}</strong>
                      {t.driver.contacts.length > 0 ? ` (${t.driver.contacts})` : ''}.
                      <br />
                      Вы поедете{' '}
                      {t.members.length === 1
                        ? ' в гордом одиночестве.'
                        : `дружной компанией вместе с ${(() => {
                            const formatter = new Intl.ListFormat('default', {
                              style: 'long',
                              type: 'conjunction',
                            });
                            return formatter.format(
                              t.members
                                .filter((x) => x.user.id !== authContext.user?.id)
                                .map(
                                  (m) =>
                                    `${m.user.name} ${m.user.surname}${m.comment.length > 0 ? ` (${m.comment})` : ''}`,
                                ),
                            );
                          })()}.`}
                    </li>
                  );
                })}
              </ol>
            </section>
          )}
        </PohCol>
      </PohRow>
    </PohContainer>
  );
};

export default HikingMy;
